import{_ as a,o as n,c as s,a2 as o}from"./chunks/framework.B7YvHKtj.js";const h=JSON.parse('{"title":"Dual-Model Pipeline Tuning Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/advanced/dual_model.md","filePath":"en/docs/advanced/dual_model.md"}'),i={name:"en/docs/advanced/dual_model.md"};function t(l,e,r,c,d,p){return n(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="dual-model-pipeline-tuning-guide" tabindex="-1">Dual-Model Pipeline Tuning Guide <a class="header-anchor" href="#dual-model-pipeline-tuning-guide" aria-label="Permalink to &quot;Dual-Model Pipeline Tuning Guide&quot;">​</a></h1><p>Traditional AI subtitle tools suffer from an awkward trade-off: line-by-line translation is either too slow for live audio playback, or disjointed without context—causing character names and idioms to fluctuate wildly from scene to scene.</p><p><strong>CoWatcher resolves this via an asynchronous Dual-Model Pipeline</strong>.</p><hr><h2 id="_1-how-it-works" tabindex="-1">1. How It Works <a class="header-anchor" href="#_1-how-it-works" aria-label="Permalink to &quot;1. How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Platform Subtitle Stream]</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span> ┌───────────────────────────┐</span></span>
<span class="line"><span> │   Translation Model       │ ◄── Enriched with Show Glossary &amp; Memory</span></span>
<span class="line"><span> └─────────────┬─────────────┘</span></span>
<span class="line"><span>               │ Lookahead batch streaming</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>   [Live Player Subtitle DOM]</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>   (Async Background Audit &amp; Extraction)</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span> ┌───────────────────────────┐</span></span>
<span class="line"><span> │   Supervisor Model        │ ──► Audits consistency, maintains names/glossary</span></span>
<span class="line"><span> └───────────────────────────┘</span></span></code></pre></div><ol><li><p><strong>Translation Model</strong>:</p><ul><li><strong>Role</strong>: Ultra-fast, responsive lookahead batch translation.</li><li><strong>Mission</strong>: Pre-translates upcoming cues 10–30 seconds ahead of the video playhead so that playback is 100% latency-free.</li><li><strong>Recommended</strong>: <code>translategemma:4b</code> (Ollama) or <code>deepseek/deepseek-chat</code> / <code>google/gemini-2.0-flash-001</code> (OpenRouter).</li></ul></li><li><p><strong>Supervisor Model</strong>:</p><ul><li><strong>Role</strong>: Reasoning, contextual summarization, and consistency auditing.</li><li><strong>Mission</strong>: Asynchronously warms up show context, reconciles character aliases, maintains terminology consistency, and flags difficult slang.</li><li><strong>Recommended</strong>: <code>qwen2.5:7b</code> (Ollama) or <code>google/gemini-2.0-flash-001</code> / <code>anthropic/claude-3.5-haiku</code> (OpenRouter).</li></ul></li></ol><hr><h2 id="_2-tuning-performance-parameters" tabindex="-1">2. Tuning Performance Parameters <a class="header-anchor" href="#_2-tuning-performance-parameters" aria-label="Permalink to &quot;2. Tuning Performance Parameters&quot;">​</a></h2><p>Tune these options in the <strong>Dual-Model Pipeline Performance Tuning</strong> section of the popup:</p><h3 id="batch-size" tabindex="-1">Batch Size <a class="header-anchor" href="#batch-size" aria-label="Permalink to &quot;Batch Size&quot;">​</a></h3><ul><li><strong>Recommended</strong>: <code>5</code> – <code>10</code> cues</li><li>Determines how many consecutive cues are grouped into a single LLM prompt. Balances syntactic coherence with prompt round-trip time.</li></ul><h3 id="lookahead-window" tabindex="-1">Lookahead Window <a class="header-anchor" href="#lookahead-window" aria-label="Permalink to &quot;Lookahead Window&quot;">​</a></h3><ul><li><strong>Recommended</strong>: <code>15</code> – <code>30</code> seconds</li><li>Determines how far ahead of the current playhead the engine pre-fetches and translates subtitles into local storage.</li></ul><h3 id="concurrency-limit" tabindex="-1">Concurrency Limit <a class="header-anchor" href="#concurrency-limit" aria-label="Permalink to &quot;Concurrency Limit&quot;">​</a></h3><ul><li><strong>Local Ollama (GPU)</strong>: Set to <code>1</code>. Prevents GPU VRAM exhaustion or serialization bottlenecks.</li><li><strong>Cloud OpenRouter</strong>: Set to <code>2</code> – <code>4</code>. Takes advantage of serverless parallelism to dramatically speed up buffer filling.</li></ul>`,16)])])}const m=a(i,[["render",t]]);export{h as __pageData,m as default};
